import torch
import torch.nn as nn

class LatticeAggregationGNN(nn.Module):
    def __init__(self, in_features: int = 8, out_features: int = 8):
        super().__init__()
        self.proj = nn.Linear(in_features, out_features)

    def forward(self, adj: torch.Tensor, x: torch.Tensor) -> torch.Tensor:
        # adj: (N, N) adjacency matrix, x: (N, D) node features
        h = self.proj(x)
        # Permutation-equivariant aggregation: f(P A P^T, P X) == P f(A, X).
        return h + torch.matmul(adj, h)

